CREATE TABLE IF NOT EXISTS `dpn_medical_death_cases` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`patient_cid` varchar(64) NOT NULL,`status` varchar(32) NOT NULL,`cause` varchar(255) NULL,`manner` varchar(64) NULL,`coroner_cid` varchar(64) NULL,`scene_data` longtext NULL,`pronounced_at` datetime NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_death_patient` (`patient_cid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
